const fs=require("fs"),assert=require("assert");
const paths=["Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json","Tasks/TasksCompleted/user-prompt-task-1794192853-accepted-instruction.json","references/user-defined-scope-rule.json"];
const wrapper=JSON.parse(fs.readFileSync(paths[0],"utf8"));
const accepted=JSON.parse(fs.readFileSync(paths[1],"utf8"));
assert(Array.isArray(wrapper) && typeof wrapper[1]==="object" && !Array.isArray(wrapper[1]));
const rule=wrapper[1];
console.log(JSON.stringify({wrapper_index_1_keys:Object.keys(rule),title:rule.title,examples_count:rule.examples?.length,accepted_keys:Object.keys(accepted),accepted_body_matches:JSON.stringify({...Object.fromEntries(Object.entries(rule).filter(([k])=>k!=="title"))})===JSON.stringify(accepted),target_exists:fs.existsSync(paths[2]),candidate_path:paths[2]},null,2));
NODE
printf '\nMETADATA\n'; test -f config/file-metadata.json && echo YES || echo NO
printf '\nSTATUS\n'; git status --short
